220	%% 5. RESULTS
221	%% ============================================================
222	\section{Results}
223	
224	\subsection{G-MFRM Model Fit}
225	\label{sec:fit}
226	
227	\begin{table}[t]
228	\centering
229	\caption{G-MFRM convergence diagnostics. The model achieves acceptable convergence: 92\% of parameters have $\hat{R} < 1.05$.}
230	\label{tab:convergence}
